        ['Одна́ кни́га — две кни́ги.','Оди́н челове́к — мно́го люде́й.'], [('сту́лья','несколько предметов для сидения','Здесь стоя́т сту́лья.','chairs'),('лю́ди','несколько человек','На у́лице лю́ди.','people'),('де́ти','несколько детей','Де́ти игра́ют.','children')],
